:root {
  --bg-card: #ffffff;
  --bg-header: #1e3a2f;
  --bg-stat-green: #d4edda;
  --bg-stat-gold: #fff3cd;
  --bg-stat-sky: #d0eaf8;
  --text-header: #ffffff;
  --text-sub: #a8c5b0;
  --text-dark: #1e3a2f;
  --text-mid: #4a6658;
  --text-light: #8aaa98;
  --badge-bg: #52b788;
  --badge-text: #ffffff;
  --accent-green: #2d6a4f;
  --accent-gold: #b07d00;
  --accent-sky: #1a7abf;
  --fill-red: #e63946;
  --fill-green: #52b788;
  --fill-orange: #f4833a;
  --fill-teal: #1b9aaa;
  --bar-bg: #e8f0eb;
  --alert-warn-bg: #fff8e1;
  --alert-warn-dot: #f0a500;
  --alert-info-bg: #e8f4fc;
  --alert-info-dot: #1a7abf;
  --alert-ok-bg: #eaf7ef;
  --alert-ok-dot: #2d9c5f;
  --border: #dde8e1;
  --footer-bg: #f0f7f3;
}

.dashboard {
  width: 480px;
  background: var(--bg-card);
  border-radius: 14px;
  overflow: hidden;
  border: 1.5px solid var(--border);
}

.dash-header {
  background: var(--bg-header);
  padding: 12px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.header-left {
  display: flex;
  align-items: center;
  gap: 10px;
}

.icon {
  font-size: 22px;
  line-height: 1;
}

.dash-title {
  font-size: 17px;
  font-weight: 700;
  color: var(--text-header);
  margin: 0;
  line-height: 1.2;
}

.dash-sub {
  font-size: 11px;
  color: var(--text-sub);
  margin: 0;
  line-height: 1.4;
}

.season-badge {
  background: var(--badge-bg);
  color: var(--badge-text);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  padding: 4px 9px;
  border-radius: 20px;
}

.main-grid {
  display: grid;
  grid-template-columns: 100px 1fr 140px;
  gap: 0;
}

.stat-col {
  display: flex;
  flex-direction: column;
  border-right: 1.5px solid var(--border);
}

.stat-card {
  display: flex;
  flex-direction: column;
  padding: 12px 10px;
  border-bottom: 1.5px solid var(--border);
  gap: 2px;
}

.stat-card:last-child {
  border-bottom: none;
  flex: 1;
}

.accent-green {
  background: var(--bg-stat-green);
}

.accent-gold {
  background: var(--bg-stat-gold);
}

.accent-sky {
  background: var(--bg-stat-sky);
}

.stat-label {
  font-size: 10px;
  font-weight: 600;
  color: var(--text-mid);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.stat-value {
  font-size: 22px;
  font-weight: 800;
  color: var(--text-dark);
  line-height: 1.1;
}

.stat-unit {
  font-size: 11px;
  font-weight: 500;
  color: var(--text-light);
}

.crops-col {
  padding: 12px 14px;
  border-right: 1.5px solid var(--border);
}

.col-heading {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-light);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin: 0 0 10px 0;
}

.crop-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.crop-item {
  display: flex;
  align-items: center;
  gap: 8px;
}

.crop-emoji {
  font-size: 15px;
  line-height: 1;
  flex-shrink: 0;
}

.crop-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.crop-name {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-dark);
  line-height: 1;
}

.progress-bar {
  height: 6px;
  background: var(--bar-bg);
  border-radius: 99px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  border-radius: 99px;
}

.fill-red { background: var(--fill-red); }
.fill-green { background: var(--fill-green); }
.fill-orange { background: var(--fill-orange); }
.fill-teal { background: var(--fill-teal); }

.crop-pct {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-mid);
  flex-shrink: 0;
  width: 28px;
  text-align: right;
}

.alert-col {
  padding: 12px 12px 0 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.alert-item {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 6px 8px;
  border-radius: 7px;
}

.alert-warn { background: var(--alert-warn-bg); }
.alert-info { background: var(--alert-info-bg); }
.alert-ok   { background: var(--alert-ok-bg); }

.alert-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
}

.alert-warn .alert-dot { background: var(--alert-warn-dot); }
.alert-info .alert-dot { background: var(--alert-info-dot); }
.alert-ok   .alert-dot { background: var(--alert-ok-dot); }

.alert-text {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-dark);
  line-height: 1.3;
}

.dash-footer {
  margin-top: auto;
  padding: 10px 0 12px 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.footer-label {
  font-size: 10px;
  font-weight: 600;
  color: var(--text-light);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.footer-date {
  font-size: 13px;
  font-weight: 700;
  color: var(--accent-green);
}
